using System;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Text;
using System.Text.Json;
using System.Windows.Forms;

namespace ScriptForge.Launcher;

/// <summary>
/// Generic host generated by ScriptForge. Extracts the embedded payload to a
/// temp folder and runs the entry script (.ps1 via powershell.exe, or .bat via
/// cmd.exe), then cleans up.
/// </summary>
internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        var manifest = LoadManifest();
        string? workDir = null;

        try
        {
            workDir = ExtractPayload(manifest);
            var entryPath = Path.Combine(workDir, manifest.Entry.Replace('/', Path.DirectorySeparatorChar));
            var exitCode = manifest.Kind switch
            {
                "ps1" => RunPowerShell(entryPath, workDir, args, manifest.Console),
                "bat" => RunBatch(entryPath, workDir, args, manifest.Console),
                _ => throw new NotSupportedException($"Unknown script kind '{manifest.Kind}'."),
            };

            if (manifest.Console && manifest.PauseOnExit)
            {
                Console.WriteLine();
                Console.Write("Press any key to close . . .");
                try
                {
                    Console.ReadKey(intercept: true);
                }
                catch (InvalidOperationException)
                {
                    // Input is redirected (e.g. launched from a script/pipe) - just read a line instead.
                    Console.ReadLine();
                }
            }

            return exitCode;
        }
        catch (Exception ex)
        {
            ReportFailure(ex.Message, manifest.Console);
            return 1;
        }
        finally
        {
            if (workDir is not null) TryCleanup(workDir);
        }
    }

    private static PayloadManifest LoadManifest()
    {
        var asm = Assembly.GetExecutingAssembly();
        using var stream = asm.GetManifestResourceStream("ScriptForge.Launcher.Payload.manifest.json")
            ?? throw new InvalidOperationException("Embedded manifest.json not found.");
        var manifest = JsonSerializer.Deserialize<PayloadManifest>(stream)
            ?? throw new InvalidOperationException("Embedded manifest.json is empty.");
        return manifest;
    }

    private static string ExtractPayload(PayloadManifest manifest)
    {
        var asm = Assembly.GetExecutingAssembly();
        var workDir = Path.Combine(Path.GetTempPath(), "ScriptForge", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(workDir);

        foreach (var file in manifest.Files)
        {
            var resourceName = "ScriptForge.Launcher.Payload." + file.Resource;
            using var resStream = asm.GetManifestResourceStream(resourceName)
                ?? throw new InvalidOperationException($"Embedded resource '{resourceName}' not found.");

            var destPath = Path.Combine(workDir, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));
            Directory.CreateDirectory(Path.GetDirectoryName(destPath)!);
            using var destStream = File.Create(destPath);
            resStream.CopyTo(destStream);
        }

        return workDir;
    }

    private static int RunPowerShell(string entryPath, string workDir, string[] args, bool console)
    {
        var psi = new ProcessStartInfo(ResolvePowerShellExe())
        {
            WorkingDirectory = workDir,
            UseShellExecute = false,
            CreateNoWindow = !console,
            WindowStyle = console ? ProcessWindowStyle.Normal : ProcessWindowStyle.Hidden,
        };

        psi.ArgumentList.Add("-NoLogo");
        psi.ArgumentList.Add("-NoProfile");
        psi.ArgumentList.Add("-ExecutionPolicy");
        psi.ArgumentList.Add("Bypass");
        psi.ArgumentList.Add("-File");
        psi.ArgumentList.Add(entryPath);
        foreach (var arg in args)
        {
            psi.ArgumentList.Add(arg);
        }

        using var proc = Process.Start(psi)!;
        proc.WaitForExit();

        if (!console && proc.ExitCode != 0)
        {
            ReportFailure($"Script exited with code {proc.ExitCode}.", console: false);
        }

        return proc.ExitCode;
    }

    private static string ResolvePowerShellExe()
    {
        var system32 = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.System),
            "WindowsPowerShell", "v1.0", "powershell.exe");
        return File.Exists(system32) ? system32 : "powershell.exe";
    }

    private static int RunBatch(string entryPath, string workDir, string[] args, bool console)
    {
        var argLine = string.Join(' ', Array.ConvertAll(args, EscapeArg));
        var psi = new ProcessStartInfo("cmd.exe")
        {
            Arguments = $"/c \"\"{entryPath}\" {argLine}\"",
            WorkingDirectory = workDir,
            UseShellExecute = false,
            CreateNoWindow = !console,
            WindowStyle = console ? ProcessWindowStyle.Normal : ProcessWindowStyle.Hidden,
        };

        using var proc = Process.Start(psi)!;
        proc.WaitForExit();

        if (!console && proc.ExitCode != 0)
        {
            ReportFailure($"Script exited with code {proc.ExitCode}.", console: false);
        }

        return proc.ExitCode;
    }

    private static string EscapeArg(string arg) =>
        arg.Contains(' ') ? $"\"{arg}\"" : arg;

    private static void ReportFailure(string message, bool console)
    {
        if (console)
        {
            Console.Error.WriteLine(message);
        }
        else
        {
            MessageBox.Show(message, "An error occurred", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private static void TryCleanup(string workDir)
    {
        try { Directory.Delete(workDir, recursive: true); }
        catch { /* best effort */ }
    }
}

internal sealed class PayloadManifest
{
    public string Entry { get; set; } = "";
    public string Kind { get; set; } = "ps1";
    public bool Console { get; set; } = true;
    public bool PauseOnExit { get; set; } = false;
    public PayloadFile[] Files { get; set; } = Array.Empty<PayloadFile>();
}

internal sealed class PayloadFile
{
    public string Resource { get; set; } = "";
    public string RelativePath { get; set; } = "";
}
